style.css:
@-moz-document domain("youtube.com") {
/* PALETA: altere as cores aqui */
  :root {
    --my-bg: #0d0a09;
    --my-sidebar: #130e0b;
    --my-panel: #211711;
    --my-raised: #302119;
    --my-amber: #ffb449;
    --my-orange: #d8782d;
    --my-gold: #f4cf84;
    --my-light: #f4dfc0;
    --my-text: #f2e9dd;
    --my-muted: #b9a797;
    --my-border: #61452d;
    --my-shadow: rgba(0,0,0,.4);
    --my-glow: rgba(255,180,73,.22);
    --my-fog: rgba(216,120,45,.09);
    --my-speed: 350ms;
  }

  /* MODO CLARO: DESERTO SOLAR */
  html:not([dark]) {
    --my-bg: #f0e6d7;
    --my-sidebar: #e5d6c2;
    --my-panel: #fff4e4;
    --my-raised: #e8d2b4;
    --my-amber: #a8500d;
    --my-orange: #9c4817;
    --my-gold: #955012;
    --my-light: #37251a;
    --my-text: #291c15;
    --my-muted: #725f51;
    --my-border: #c5a37e;
    --my-shadow: rgba(64,37,17,.12);
    --my-glow: rgba(168,80,13,.13);
    --my-fog: rgba(216,120,45,.05);
  }

  /* INTEGRAÇÃO COM O YOUTUBE */
  html,
  html[dark],
  ytd-app {
    --yt-spec-base-background: var(--my-bg) !important;
    --yt-spec-general-background-a: var(--my-bg) !important;
    --yt-spec-general-background-b: var(--my-panel) !important;
    --yt-spec-general-background-c: var(--my-raised) !important;
    --yt-spec-raised-background: var(--my-panel) !important;
    --yt-spec-menu-background: var(--my-panel) !important;
    --yt-spec-text-primary: var(--my-text) !important;
    --yt-spec-text-secondary: var(--my-muted) !important;
    --yt-spec-icon-inactive: var(--my-muted) !important;
    --yt-spec-icon-active: var(--my-amber) !important;
    --yt-spec-brand-icon-active: var(--my-amber) !important;
    --yt-spec-static-brand-red: var(--my-orange) !important;
    --yt-spec-outline: var(--my-border) !important;
  }

  /* FUNDO: ARQUITETURA E NÉVOA */
  html,
  body,
  ytd-app {
    background-color: var(--my-bg) !important;
    color: var(--my-text) !important;
    font-family:
      "Segoe UI", Roboto, Arial, sans-serif !important;
  }

  ytd-app {
    background-image:
      radial-gradient(
        ellipse at 75% 0%,
        var(--my-fog),
        transparent 58%
      ),
      linear-gradient(
        90deg,
        transparent 0%,
        rgba(216,120,45,.025) 50%,
        transparent 100%
      ),
      repeating-linear-gradient(
        90deg,
        transparent 0,
        transparent 159px,
        rgba(216,120,45,.025) 160px
      ) !important;
    background-attachment: fixed !important;
  }

  /* CABEÇALHO: LUZ LINEAR WALLACE */
  ytd-masthead,
  #background.ytd-masthead {
    background: linear-gradient(
      100deg,
      var(--my-sidebar) 0%,
      var(--my-panel) 52%,
      var(--my-sidebar) 100%
    ) !important;
    border-bottom: 1px solid var(--my-border) !important;
    box-shadow:
      0 3px 22px var(--my-shadow),
      0 1px 12px var(--my-glow) !important;
  }

  ytd-masthead {
    animation: my-arrival 650ms ease-out both;
  }

  /* MARCA DO TERMINAL */
  #logo.ytd-masthead {
    position: relative !important;
  }

  #logo.ytd-masthead::after {
    content: "2049";
    position: absolute;
    right: -2px;
    bottom: -9px;
    color: var(--my-amber);
    font: 700 9px monospace;
    letter-spacing: 2px;
    pointer-events: none;
  }

  /* BUSCA: CONSOLE DE INVESTIGAÇÃO */
  #container.ytd-searchbox,
  ytd-searchbox #container {
    background: var(--my-panel) !important;
    border: 1px solid var(--my-border) !important;
    border-radius: 3px 0 0 3px !important;
    box-shadow:
      inset 0 1px 8px rgba(0,0,0,.1) !important;
    transition:
      border-color var(--my-speed),
      box-shadow var(--my-speed) !important;
  }

  #container.ytd-searchbox:focus-within,
  ytd-searchbox #container:focus-within {
    border-color: var(--my-amber) !important;
    box-shadow:
      0 0 0 1px var(--my-amber),
      0 0 24px var(--my-glow) !important;
  }

  #search.ytd-searchbox,
  #container.ytd-searchbox input {
    background: transparent !important;
    color: var(--my-text) !important;
    caret-color: var(--my-amber) !important;
  }

  #search-icon-legacy.ytd-searchbox {
    background: var(--my-raised) !important;
    color: var(--my-amber) !important;
    border: 1px solid var(--my-border) !important;
    border-radius: 0 3px 3px 0 !important;
  }

  #search-icon-legacy.ytd-searchbox:hover {
    background: var(--my-amber) !important;
    color: var(--my-bg) !important;
    box-shadow: 0 0 22px var(--my-glow) !important;
  }

  /* BARRA LATERAL: ARQUIVO LAPD */
  #guide-content.ytd-app,
  ytd-mini-guide-renderer {
    background: var(--my-sidebar) !important;
    border-right: 1px solid var(--my-border) !important;
  }

  #guide-section-title.ytd-guide-section-renderer {
    color: var(--my-amber) !important;
    font-family: monospace !important;
    font-size: 11px !important;
    letter-spacing: 2px !important;
    text-transform: uppercase !important;
  }

  ytd-guide-entry-renderer,
  ytd-mini-guide-entry-renderer {
    transition:
      background var(--my-speed),
      transform var(--my-speed),
      box-shadow var(--my-speed) !important;
  }

  ytd-guide-entry-renderer:hover,
  ytd-mini-guide-entry-renderer:hover {
    background: var(--my-raised) !important;
    box-shadow: inset 2px 0 var(--my-orange) !important;
    transform: translateX(3px);
  }

  ytd-guide-entry-renderer[active],
  ytd-mini-guide-entry-renderer[active] {
    background: var(--my-panel) !important;
    border-left: 3px solid var(--my-amber) !important;
    box-shadow: inset 0 0 15px var(--my-glow) !important;
  }

  .guide-icon.ytd-guide-entry-renderer,
  .guide-icon.ytd-mini-guide-entry-renderer {
    color: var(--my-muted) !important;
  }

  ytd-guide-entry-renderer[active] .guide-icon,
  ytd-mini-guide-entry-renderer[active] .guide-icon {
    color: var(--my-amber) !important;
  }

  /* FILTROS: BOTÕES INDUSTRIAIS */
  #chips-wrapper.ytd-feed-filter-chip-bar-renderer,
  yt-chip-cloud-renderer {
    background: var(--my-bg) !important;
    border-bottom: 1px solid var(--my-border) !important;
  }

  yt-chip-cloud-chip-renderer {
    border-radius: 4px !important;
    transition:
      transform 250ms,
      box-shadow 250ms,
      filter 250ms !important;
  }

  yt-chip-cloud-chip-renderer[chip-style][selected] {
    background: var(--my-amber) !important;
    color: var(--my-bg) !important;
    border: 1px solid var(--my-amber) !important;
    box-shadow: 0 0 15px var(--my-glow) !important;
  }

  yt-chip-cloud-chip-renderer:hover {
    transform: translateY(-2px);
    filter: brightness(1.12);
  }

  /* MINIATURAS: JANELAS CINEMATOGRÁFICAS */
  ytd-thumbnail {
    position: relative !important;
    overflow: hidden !important;
    border-radius: 4px !important;
    outline: 1px solid var(--my-border) !important;
    outline-offset: -1px;
    transition:
      transform 420ms cubic-bezier(.2,.8,.2,1),
      outline-color 300ms,
      box-shadow 420ms !important;
  }

  ytd-thumbnail:hover {
    transform: translateY(-3px) scale(1.012);
    outline-color: var(--my-amber) !important;
    box-shadow:
      0 12px 30px var(--my-shadow),
      0 0 20px var(--my-glow) !important;
  }

  /* LUZ ÂMBAR SUTIL SOBRE MINIATURAS */
  ytd-thumbnail::after {
    content: "";
    position: absolute;
    inset: 0;
    pointer-events: none;
    background: linear-gradient(
      145deg,
      rgba(255,180,73,.065),
      transparent 45%,
      rgba(27,12,3,.05)
    );
    opacity: .55;
    transition: opacity 400ms;
  }

  ytd-thumbnail:hover::after {
    opacity: .9;
  }

  /* IDENTIFICAÇÃO DOS VÍDEOS */
  #video-title,
  #video-title-link,
  h1.ytd-watch-metadata {
    color: var(--my-text) !important;
    font-weight: 650 !important;
    letter-spacing: .1px !important;
    transition: color 250ms !important;
  }

  #video-title:hover,
  #video-title-link:hover {
    color: var(--my-amber) !important;
  }

  #metadata-line,
  #byline,
  #channel-name {
    color: var(--my-muted) !important;
  }

  /* CARTÕES: PROFUNDIDADE */
  ytd-rich-grid-media,
  ytd-video-renderer,
  ytd-compact-video-renderer {
    transition:
      background 320ms,
      box-shadow 320ms !important;
  }

  ytd-rich-grid-media:hover,
  ytd-video-renderer:hover,
  ytd-compact-video-renderer:hover {
    background: var(--my-fog) !important;
    box-shadow: inset 2px 0 var(--my-orange) !important;
  }

  /* REPRODUTOR: MOLDURA LIMPA */
  .html5-video-player {
    border: 1px solid var(--my-border) !important;
    box-shadow:
      0 0 0 1px var(--my-bg),
      0 0 24px var(--my-shadow) !important;
  }

  /* PROGRESSO: ÂMBAR LUMINOSO */
  .ytp-play-progress,
  .ytp-swatch-background-color {
    background: var(--my-amber) !important;
  }

  .ytp-load-progress {
    background: var(--my-border) !important;
  }

  .ytp-volume-level {
    background: var(--my-orange) !important;
  }

  .ytp-scrubber-button {
    background: var(--my-amber) !important;
    border: 2px solid #130e0b !important;
    box-shadow: 0 0 13px rgba(255,180,73,.5) !important;
  }

  /* A COR DO FILME REPRODUZIDO NÃO É ALTERADA */

  /* BOTÕES DE INTERAÇÃO */
  ytd-watch-metadata button,
  yt-button-shape button {
    transition:
      transform 240ms,
      box-shadow 240ms,
      filter 240ms !important;
  }

  ytd-watch-metadata button:hover,
  yt-button-shape button:hover {
    transform: translateY(-2px);
    box-shadow: 0 4px 16px var(--my-glow) !important;
  }

  ytd-subscribe-button-renderer button {
    border: 1px solid var(--my-amber) !important;
    box-shadow: 0 0 10px var(--my-glow) !important;
  }

  /* MENUS: PAINÉIS CORPORATIVOS */
  ytd-menu-popup-renderer,
  ytd-multi-page-menu-renderer,
  tp-yt-paper-listbox {
    background: var(--my-panel) !important;
    color: var(--my-text) !important;
    border: 1px solid var(--my-border) !important;
    border-top: 2px solid var(--my-amber) !important;
    border-radius: 5px !important;
    box-shadow:
      0 14px 36px var(--my-shadow),
      0 0 18px var(--my-glow) !important;
    animation: my-panel-entry 300ms ease-out;
  }

  tp-yt-paper-item:hover,
  ytd-menu-service-item-renderer:hover {
    background: var(--my-raised) !important;
    color: var(--my-amber) !important;
  }

  /* PLAYLISTS: ARQUIVOS DE MEMÓRIA */
  #container.ytd-playlist-panel-renderer,
  ytd-playlist-sidebar-renderer {
    background: var(--my-panel) !important;
    border: 1px solid var(--my-border) !important;
    border-radius: 5px !important;
  }

  .header.ytd-playlist-panel-renderer {
    background: var(--my-raised) !important;
    border-bottom: 2px solid var(--my-amber) !important;
  }

  .playlist-items.ytd-playlist-panel-renderer {
    background: var(--my-panel) !important;
  }

  /* COMENTÁRIOS: REGISTROS */
  ytd-comment-thread-renderer {
    border-left: 2px solid transparent !important;
    transition:
      background 300ms,
      border-color 300ms !important;
  }

  ytd-comment-thread-renderer:hover {
    background: var(--my-fog) !important;
    border-left-color: var(--my-orange) !important;
  }

  /* SELEÇÃO E FOCO */
  ::selection {
    background: var(--my-orange) !important;
    color: #100a05 !important;
  }

  a:focus-visible,
  button:focus-visible,
  input:focus-visible {
    outline: 2px solid var(--my-amber) !important;
    outline-offset: 2px !important;
  }

  /* BARRAS DE ROLAGEM */
  ::-webkit-scrollbar {
    width: 9px;
    height: 9px;
  }

  ::-webkit-scrollbar-thumb {
    background: var(--my-border);
    border-radius: 8px;
  }

  ::-webkit-scrollbar-thumb:hover {
    background: var(--my-orange);
  }

  /* ANIMAÇÃO: INICIALIZAÇÃO */
  @keyframes my-arrival {
    from {
      opacity: .4;
      transform: translateY(-12px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  /* ANIMAÇÃO: ENTRADA DE PAINÉIS */
  @keyframes my-panel-entry {
    from {
      opacity: 0;
      transform: translateY(8px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  /* ANIMAÇÃO: TERMINAL ATIVO */
  @keyframes my-amber-pulse {
    0%,100% {
      box-shadow: 0 0 3px var(--my-glow);
    }
    50% {
      box-shadow: 0 0 17px var(--my-glow);
    }
  }

  ytd-guide-entry-renderer[active],
  yt-chip-cloud-chip-renderer[chip-style][selected] {
    animation: my-amber-pulse 3.6s ease-in-out infinite;
  }

  /* ACESSIBILIDADE */
  @media (prefers-reduced-motion: reduce) {
    ytd-masthead,
    ytd-menu-popup-renderer,
    ytd-multi-page-menu-renderer,
    ytd-guide-entry-renderer[active],
    yt-chip-cloud-chip-renderer[chip-style][selected] {
      animation: none !important;
    }
  }
}
